                    margin-right: 10px;
                    gap: 5px;
                  "
                >
                  <SvgIcon name="dot_circle"></SvgIcon>

                  {{ rows.id }}
                </td>
                <td>{{ rows.restName }}</td>
                <td>{{ rows.productCount }}</td>
                <td>{{ rows.orderCount }}</td>
                <td>{{ formatDate(rows.lastPurchase) }}</td>
                <td class="actions">
                  <div class="iconsIctions">
                    <div class="icon" @click="openPopup('edit', rows)">
                      <SvgIcon class="svg" name="edit"></SvgIcon>
                    </div>
                    <div class="icon" @click="openPopup('view', rows)">
                      <SvgIcon class="svg" name="view"></SvgIcon>
                    </div>
                    <div v-if="!rows.approved" class="icon" @click="openPopup('approve', rows)">
                      <i class="fa-solid fa-circle-check svg approve"></i>
                    </div>
                    <div v-if="rows.approved"  >
                    </div>
                    <div class="icon" @click="openPopup('delete', rows)">
                      <SvgIcon class="svg delete" name="deleteItem"></SvgIcon>
                    </div>
                    <div class="icon" @click="openPopup('commission', rows)">
                      <template v-if="rows.commission === 0 || rows.commission === '0' || rows.commission === '0.00' || (rows.commission && (rows.commission.value === 0 || rows.commission.value === '0.00'))">
                        <i class="fa-solid fa-percentage svg commission" :title="$t('setCommission')"></i>
                      </template>
                      <template v-else-if="!rows.is_restaurant_have_commission">
                        <i class="fa-solid fa-percentage svg commission" :title="$t('setCommission')"></i>
                      </template>
                      <template v-else>
                        <i class="fa-solid fa-pen-to-square svg commission" :title="$t('updateCommission')"></i>
                      </template>
                    </div>
                  </div>
                </td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    </div>
    <dashboardPopup
      v-if="isPopupVisible"
      :type="popupType"
      :row="selectedRow"
      @close="closePopup"
      @save="handlePopupSave"
    />
  </div>
</template>

<script>
import boxDetails from "@/components/dashboard/boxDetails.vue";
import DashboardPopup from "@/components/dashboard/popus/dashboardPopup.vue";
import axios from "axios";
import SvgIcon from "@/components/SvgIcon.vue";
import LoadingHere from "@/components/LoadingHere.vue"; // Import LoadingHere component
import { getLocalizedNameWithI18n } from "@/utils/localization.js";

export default {
  name: "RestaurantManagement",
  components: {
    boxDetails,
    DashboardPopup,
    LoadingHere,
    SvgIcon,
  },
  data() {
    return {
      filter: "",
      rows: [
        // More products here
      ],
      isPopupVisible: false,
      popupType: "",
      selectedRow: {},
      isLoading: false, // Add loading state
      canAddRestaurants: false, // Disable restaurant creation by default
    };
  },

  mounted() {
    this.isLoading = true;
    this.FetchRows(); // Fetch rows dynamically

    this.fetchUserData(); // Fetch user data dynamically
    if (this.$toast) {
      this.$toast.success("Welcome to your dashboard!");
    }
  },
  computed: {
    filteredRows() {
      return this.rows.filter((row) => {
        const searchTerm = this.filter.toLowerCase();
        return (
          (typeof row.restName === "string" &&
            row.restName.toLowerCase().includes(searchTerm)) ||
          (row.id && row.id.toString().toLowerCase().includes(searchTerm))
        );
      });
    },
  },
  methods: {
    fetchUserData() {
      // Simulate fetching user data from an API or store
    },
    FetchRows() {
      const token = localStorage.getItem("authToken");
      axios
        .get(
          "https://backend.alaqdk.com/api/v1/admin/dashboard/get-all-restaurants",
          {
            headers: {
              "Accept-Language": "ar",
              Authorization: `Bearer ${token}`, // Add the Authorization header
            },
          }
        )
        .then((response) => {
          this.isLoading = false;
          console.log("Restaurant Response:", response.data); // Log the response
          const data = response.data;
          
          // Check if data exists and has the expected structure
          if (data && data.status && data.data && Array.isArray(data.data)) {
            this.rows = data.data
              .filter((item) => item && item.id) // Filter out items without id
              .map((item) => ({
                id: item.id || `restaurant_${Date.now()}_${Math.random()}`,
                restName: getLocalizedNameWithI18n(item.name, this.$i18n) || "N/A",
                email: item.email || "",
                phone: item.phone || "",
                productCount: item.total_products || 0,
                orderCount: item.total_orders || 0,
                lastPurchase: item.last_order || "No orders yet",
                approved: Boolean(item.approved && item.approved !== 0 && item.approved !== '0'),
                logo: item.logo || "",
                description: item.description || "",
                name_on_trading_licence: item.name_on_trading_licence || "",
                legal_name: item.legal_name || "",
                vat_enabled: item.vat_enabled || 0,
                banner: item.banner || null,
                total_review: item.total_review || "0.0",
                open_time: item.open_time || null,
                close_time: item.close_time || null,
                personal_nid: item.personal_nid || "",
                trading_type: item.trading_type || "",
                created_at: item.created_at || "",
                updated_at: item.updated_at || "",
                is_restaurant_have_commission: item.is_restaurant_have_commission || false,
                commission: item.commission || null,
              }));
            console.log("Processed rows:", this.rows);
            // Debug approved status
            this.rows.forEach((row, index) => {
              console.log(`Row ${index}: ID=${row.id}, Name=${row.restName}, Approved=${row.approved} (type: ${typeof row.approved})`);
            });
          } else {
            console.error("Failed to fetch rows data: Invalid data structure", data);
            this.rows = []; // Set empty array if data is invalid
          }
        })
        .catch((error) => {
          this.isLoading = false; // Set loading state to false
          console.error("Error fetching rows data:", error);
          this.rows = []; // Set empty array on error
        });
    },
    openPopup(type, row) {
      console.log(`Opening popup of type: ${type}`, row); // Debugging log
      this.popupType = type;
      this.selectedRow = { ...row };
      this.isPopupVisible = true;
    },
    closePopup() {
      this.isPopupVisible = false;
    },
    handlePopupSave(updatedData) {
      console.log("Popup save event received with data:", updatedData);
      
      // Close popup first
      this.closePopup();
      
      // Show loading state
      this.isLoading = true;
      
      // Update local data immediately if we have the updated data
      if (updatedData && updatedData.id) {
        console.log("Looking for row with ID:", updatedData.id);
        console.log("Current rows:", this.rows);
        
        const index = this.rows.findIndex(row => row.id == updatedData.id); // Use == for type coercion
        console.log("Found row at index:", index);
        
        if (index !== -1) {
          // Update the existing row with new data
          const oldRow = this.rows[index];
          
          // Create a new array to force Vue reactivity
          const updatedRows = [...this.rows];
          const newRestName = updatedData.restName || updatedData.nameEn || this.rows[index].restName;
          
          updatedRows[index] = {
            ...this.rows[index],
            restName: newRestName + ' (Updated)',
            email: updatedData.email || this.rows[index].email,
            phone: updatedData.phone || this.rows[index].phone,
          };
          
          // Replace the entire array to trigger reactivity
          this.rows = updatedRows;
          
          // Force component to re-render
          this.$forceUpdate();
          
          console.log("Old row:", oldRow);
          console.log("Updated local row:", this.rows[index]);
        } else {
          console.log("Row not found for ID:", updatedData.id);
        }
      }
      
      // Add a small delay to ensure backend has processed the update
      setTimeout(() => {
        console.log("Refreshing data from API...");
        this.FetchRows();
              }, 500);
      },
      formatDate(dateString) {
      if (!dateString || dateString === "N/A") {
        return "N/A";
      }
      
      try {
        const date = new Date(dateString);
        
        // Check if date is valid
        if (isNaN(date.getTime())) {
          return "Invalid Date";
        }
        
        // Compact date format - always use Gregorian calendar
        const options = {
          year: '2-digit',
          month: '2-digit',
          day: '2-digit',
          hour: '2-digit',
          minute: '2-digit',
          calendar: 'gregory' // Force Gregorian calendar
        };
        
        return date.toLocaleDateString(this.$i18n.locale === 'ar' ? 'ar-SA-u-ca-gregory' : 'en-US', options);
      } catch (error) {
        console.error('Error formatting date:', error);
        return dateString;
      }
    },
  },
};
